exercise.solution:
function can(user: { id: string; roles: string[] } | null, action: "read" | "update" | "delete", task: { id: string; ownerId: string; shared: boolean }): boolean {
  if (user === null) {
    return false;
  }

  if (user.roles.includes("ADMIN")) {
    return true;
  }

  const isOwner = user.id === task.ownerId;

  if (isOwner) {
    return true;
  }

  return action === "read" && task.shared;
}

function statusFor(user: { id: string; roles: string[] } | null, allowed: boolean): number {
  if (user === null) {
    return 401;
  }

  return allowed ? 200 : 403;
}
